mapper.select:
SELECT COALESCE(SUM(p.confirmed_total),0) purchase_amount,
 AVG(CASE WHEN p.status='RECEIVED' THEN TIMESTAMPDIFF(MICROSECOND,p.ordered_at,p.received_at)/1000000.0 END) average_arrival_seconds
 FROM repair_purchase_orders p JOIN repair_tickets t ON t.id=p.ticket_id WHERE p.status IN ('ORDERED','PARTIALLY_RECEIVED','RECEIVED') AND p.ordered_at>=#{from} AND p.ordered_at<#{to} AND t.store_id=#{storeId}

SELECT m.user_id id,m.display_name name,COALESCE(q.completed,0) completed,COALESCE(q.open,0) `open`,COALESCE(q.returned,0) returned,q.average_repair_seconds
 FROM repair_members m LEFT JOIN (SELECT t.assignee_id,SUM(t.completed_at>=#{period.from} AND t.completed_at<#{period.to}) completed,SUM() `open`,SUM(CASE WHEN t.completed_at>=#{period.from} AND t.completed_at<#{period.to} THEN COALESCE(r.returned,0) ELSE 0 END) returned,AVG(CASE WHEN t.completed_at>=#{period.from} AND t.completed_at<#{period.to} THEN TIMESTAMPDIFF(MICROSECOND,t.first_started_at,t.completed_repair_at)/1000000.0 END) average_repair_seconds
 FROM repair_tickets t LEFT JOIN (SELECT ticket_id,COUNT(*) returned FROM repair_ticket_events WHERE action='return' GROUP BY ticket_id) r ON r.ticket_id=t.id t.store_id=#{period.storeId} GROUP BY t.assignee_id) q ON q.assignee_id=m.user_id WHERE m.role='ENGINEER' ORDER BY m.user_id LIMIT #{size} OFFSET #{offset}

SELECT t.id,t.ticket_no,t.title,s.name store_name,t.priority,t.status,t.assigned_at
FROM repair_tickets t JOIN repair_stores s ON s.id=t.store_id WHERE 
ORDER BY (t.priority='URGENT') DESC,t.assigned_at,t.id LIMIT #{size} OFFSET #{offset}
